import { describe, expect, it } from 'vitest';
import {
  entityDiagram,
  type Cardinality,
  type EntityModel,
} from '../../../../src/domain/diagrams/entity-diagram.js';
import { demoModel } from '../../../support/diagram-fixtures.js';

// RF-262, RF-508: the entity-relationship diagram, generated by code from the entities of the
// ENT cards; a cardinality the cards do not state is drawn as unknown, never guessed.

const linesOf = (text: string): readonly string[] => text.trimEnd().split('\n');

function pair(fromCardinality: Cardinality, toCardinality: Cardinality): EntityModel {
  return {
    entities: [
      { cardId: 'ENT-001', name: 'A', fields: [] },
      { cardId: 'ENT-002', name: 'B', fields: [] },
    ],
    relations: [{ from: 'ENT-001', to: 'ENT-002', label: 'r', fromCardinality, toCardinality }],
  };
}

const stated: readonly (readonly [Cardinality, Cardinality, string])[] = [
  ['one', 'one', '  e1 ||--|| e2 : "r"'],
  ['zero-or-one', 'zero-or-one', '  e1 |o--o| e2 : "r"'],
  ['zero-or-more', 'zero-or-more', '  e1 }o--o{ e2 : "r"'],
  ['one-or-more', 'one-or-more', '  e1 }|--|{ e2 : "r"'],
];

describe('entityDiagram', () => {
  it('RF-262 draws the demo data model (snapshot)', () => {
    expect(entityDiagram(demoModel())).toMatchSnapshot();
  });

  it('RF-262 one entity per card with its fields and keys, ids generated', () => {
    expect(linesOf(entityDiagram(demoModel())).slice(0, 10)).toEqual([
      'erDiagram',
      '  e1["Customer"] {',
      '    field f1 PK "Id#58; int"',
      '    field f2 UK "Email#58; nvarchar#40;200#41;"',
      '  }',
      '  e2["Order"] {',
      '    field f1 PK "Id#58; int"',
      '    field f2 FK "CustomerId#58; int"',
      '    field f3 "Notes"',
      '  }',
    ]);
  });

  it('RF-262 an entity without fields is drawn as a name only', () => {
    expect(linesOf(entityDiagram(demoModel()))).toContain('  e3["OrderLine"]');
  });

  it('RF-262 a field with several keys lists them all', () => {
    const model: EntityModel = {
      entities: [{ cardId: 'ENT-001', name: 'A', fields: [{ name: 'Id', keys: ['PK', 'FK'] }] }],
      relations: [],
    };

    expect(linesOf(entityDiagram(model))).toContain('    field f1 PK, FK "Id"');
  });
});

describe('entityDiagram order and cardinalities', () => {
  it('RF-262 entities are drawn in card id order', () => {
    const model = demoModel();
    const reversed: EntityModel = { ...model, entities: [...model.entities].reverse() };

    expect(entityDiagram(reversed)).toBe(entityDiagram(model));
  });

  it.each(stated)('RF-262 a stated cardinality %s to %s is drawn as stated', (from, to, line) => {
    expect(linesOf(entityDiagram(pair(from, to))).at(-1)).toBe(line);
  });

  it('RF-262 an unknown cardinality is drawn dotted, open on that side, and says so', () => {
    expect(linesOf(entityDiagram(pair('one', 'unknown'))).at(-1)).toBe(
      '  e1 ||..o{ e2 : "r #40;cardinality unknown#41;"',
    );
    expect(linesOf(entityDiagram(pair('unknown', 'one'))).at(-1)).toBe(
      '  e1 }o..|| e2 : "r #40;cardinality unknown#41;"',
    );
  });
});

describe('entityDiagram missing entities and hostile names', () => {
  it('RF-262 a relation to an entity without a card gets its own entity once', () => {
    const model: EntityModel = {
      entities: [{ cardId: 'ENT-001', name: 'A', fields: [] }],
      relations: [
        {
          from: 'ENT-001',
          to: 'ENT-404',
          label: 'r',
          fromCardinality: 'one',
          toCardinality: 'one',
        },
        {
          from: 'ENT-404',
          to: 'ENT-001',
          label: 's',
          fromCardinality: 'one',
          toCardinality: 'one',
        },
      ],
    };

    expect(linesOf(entityDiagram(model))).toEqual([
      'erDiagram',
      '  e1["A"]',
      '  e2["ENT#45;404"]',
      '  e1 ||--|| e2 : "r"',
      '  e2 ||--|| e1 : "s"',
    ]);
  });

  it('RF-508 entity and field names never reach a syntax position', () => {
    const model: EntityModel = {
      entities: [
        {
          cardId: 'end',
          name: 'x"] {\n  }\n  click e1 href "javascript:x"',
          fields: [{ name: 'PK "x"\n  }', type: 'int PK' }],
        },
      ],
      relations: [],
    };

    expect(linesOf(entityDiagram(model))).toHaveLength(4);
    expect(linesOf(entityDiagram(model))[2]).toMatch(/^ {4}field f1 "[^"]*"$/);
  });
});
